import idna.codec


def create_incremental_decoder(errors: str = "strict") -> dict[str, object]:
    """Create an incremental IDNA 2008 decoder for processing data in chunks. errors: The error handling strategy for decoding, only 'strict' is supported. Example: create_incremental_decoder('strict') -> {'decoder': <IncrementalDecoder>}."""
    if errors != "strict":
        raise ValueError(f'Unsupported error handling "{errors}", only "strict" is supported')

    try:
        decoder = idna.codec.IncrementalDecoder(errors)
        return {"decoder": decoder}
    except Exception as e:
        raise ValueError(f"Failed to create incremental decoder: {str(e)}")
