def create_idna_codec(data: str, operation: str) -> str | bytes:
    """Create a stateless IDNA 2008 codec for encoding and decoding. data: The string to encode or decode using IDNA 2008, operation: Either 'encode' or 'decode'. Example: create_idna_codec('example.com', 'encode') -> b'example.com'."""
    codec = idna.codec.Codec()

    if operation == "encode":
        try:
            result, _ = codec.encode(data, "strict")
            return result
        except IDNAError as e:
            raise ValueError(f"IDNA encoding failed: {str(e)}")
    elif operation == "decode":
        try:
            result, _ = codec.decode(data, "strict")
            return result
        except IDNAError as e:
            raise ValueError(f"IDNA decoding failed: {str(e)}")
    else:
        raise ValueError(f"Invalid operation: {operation!r}. Must be 'encode' or 'decode'.")
