        encoded = label.encode('ascii')
        return idna.compat.ToUnicode(encoded)
    except UnicodeEncodeError:
        # If that fails, it's already a Unicode string, so we need to handle it properly
        try:
            # For Unicode strings, we need to use the proper IDNA decoding
            import idna
            return idna.decode(label)
        except Exception as e:
